using System;
using System.Diagnostics;
using System.Diagnostics.CodeAnalysis;
using System.Globalization;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Threading;

namespace Alternet.UI
{
    /// <summary>
    /// Represents an object identifier backed by a numeric value or a GUID.
    /// Numeric identifiers generated by the default constructors are unique within
    /// a single running instance of the application, but may overlap between
    /// separate instances.
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    public readonly struct ObjectUniqueId : IEquatable<ObjectUniqueId>
    {
        /// <summary>
        /// Represents an empty <see cref="ObjectUniqueId"/> instance.
        /// </summary>
        public static readonly ObjectUniqueId Empty = CreateEmpty();

        private static long globalCounter;

        private readonly Guid guid;
        private readonly long id;
        private readonly int hashCode;
        private readonly StateKind state;

        static ObjectUniqueId()
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/> struct.
        /// </summary>
        public ObjectUniqueId()
            : this(ref globalCounter)
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/> struct with an option
        /// to use GUID for unique id generation.
        /// If <paramref name="useGuid"/> is <c>true</c>, a GUID will be used for the unique id.
        /// </summary>
        /// <param name="useGuid">A value indicating whether to use GUID for unique id generation.</param>
        /// <remarks>
        /// When <paramref name="useGuid"/> is <see langword="false"/>, the identifier
        /// is generated from the process-local counter. Use GUID-based identifiers
        /// when identifiers need to remain unique across process runs in practice.
        /// </remarks>
        public ObjectUniqueId(bool useGuid)
            : this(ref globalCounter, useGuid)
        {
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/> struct
        /// using the specified counter.
        /// </summary>
        /// <param name="counter">
        /// A reference to the counter used to generate numeric identifiers.
        /// Share the same counter between callers that need IDs unique relative
        /// to one another, and do not reset it while those IDs are in use.
        /// </param>
        /// <param name="useGuid">
        /// If <see langword="true"/>, generates a GUID-based identifier without
        /// using the counter.
        /// </param>
        /// <remarks>
        /// <para>
        /// If <paramref name="useGuid"/> is <see langword="false"/> and the counter
        /// is non-negative, a numeric identifier is generated from it.
        /// </para>
        /// <para>
        /// <see cref="long.MinValue"/> is reserved as a sentinel that causes
        /// GUID-based identifiers to be generated. Any other negative counter value
        /// switches the counter to this sentinel; the current and subsequent calls
        /// using that counter generate GUID-based identifiers.
        /// </para>
        /// </remarks>
        public ObjectUniqueId(ref long counter, bool useGuid = false)
        {
            if (useGuid)
            {
                state = StateKind.Guid;
                guid = Guid.NewGuid();
                id = default;
                hashCode = guid.GetHashCode();
                return;
            }

            if (Volatile.Read(ref counter) == long.MinValue)
            {
                state = StateKind.Guid;
                guid = Guid.NewGuid();
                id = default;
                hashCode = guid.GetHashCode();
                return;
            }

            long next = Interlocked.Increment(ref counter);

            if (next <= 0)
            {
                Interlocked.Exchange(ref counter, long.MinValue);

                state = StateKind.Guid;
                guid = Guid.NewGuid();
                id = default;
                hashCode = guid.GetHashCode();
                return;
            }

            long value = next - 1;

            state = StateKind.Long;
            id = value;
            guid = default;
            hashCode = id.GetHashCode();
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/> struct
        /// using the specified long identifier. This constructor does not allocate the value or verify its uniqueness.
        /// </summary>        
        /// <remarks>This constructor is used to wrap existing long identifiers
        /// to <see cref="ObjectUniqueId"/>.</remarks>
        /// <param name="id">The long identifier.</param>
        public ObjectUniqueId(long id)
        {
            if (id < 0)
                throw new ArgumentOutOfRangeException(nameof(id), "Numeric ids must be >= 0.");

            state = StateKind.Long;
            this.id = id;
            guid = default;
            hashCode = id.GetHashCode();
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/>
        /// struct using the specified GUID.
        /// You should normally use the parameterless constructor.
        /// </summary>
        /// <param name="guid">The globally unique identifier (GUID) that represents
        /// the unique identity of the object.</param>
        public ObjectUniqueId(Guid guid)
        {
            state = StateKind.Guid;
            this.guid = guid;
            id = default;
            hashCode = guid.GetHashCode();
        }

        /// <summary>
        /// Initializes a new instance of the <see cref="ObjectUniqueId"/> struct
        /// with the specified state, integer identifier, GUID, and hash code.
        /// </summary>
        /// <param name="state">The state of the <see cref="ObjectUniqueId"/>.</param>
        /// <param name="id">The integer identifier.</param>
        /// <param name="guid">The globally unique identifier (GUID).</param>
        /// <param name="hashCode">The hash code of the unique identifier.</param>
        private ObjectUniqueId(StateKind state, long id, Guid guid, int hashCode)
        {
            this.state = state;
            this.id = id;
            this.guid = guid;
            this.hashCode = hashCode;
        }

        /// <summary>
        /// Defines the state of the <see cref="ObjectUniqueId"/> struct, indicating
        /// whether the unique identifier is based on a long integer or a GUID.
        /// </summary>
        public enum StateKind : byte
        {
            /// <summary>
            /// Unique identifier is not set or is in an uninitialized state.
            /// </summary>
            None,

            /// <summary>
            /// Unique identifier is represented as a long value.
            /// </summary>
            Long,

            /// <summary>
            /// Unique identifier is represented as a GUID value.
            /// </summary>
            Guid,
        }

        /// <summary>
        /// Gets the state of the <see cref="ObjectUniqueId"/> instance, indicating 
        /// whether the unique identifier is based on a long integer or a GUID.
        /// </summary>
        public StateKind State => state;

        /// <summary>
        /// Gets the long integer identifier of the <see cref="ObjectUniqueId"/> instance.
        /// </summary>
        public long IdentifierLong => id;

        /// <summary>
        /// Gets the GUID identifier of the <see cref="ObjectUniqueId"/> instance.
        /// </summary>
        public Guid IdentifierGuid => guid;

        /// <summary>
        /// Tests whether two <see cref='ObjectUniqueId'/> objects are not equal.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator !=(ObjectUniqueId left, ObjectUniqueId right)
        {
            return !(left == right);
        }

        /// <summary>
        /// Tests whether two <see cref='ObjectUniqueId'/> objects are equal.
        /// </summary>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static bool operator ==(ObjectUniqueId left, ObjectUniqueId right)
        {
            if (left.state != right.state)
                return false;

            if (left.state == StateKind.None)
                return true;

            if (left.state == StateKind.Guid)
                return left.guid == right.guid;
            return left.id == right.id;
        }

        /// <summary>
        /// Converts a string representation of an object unique identifier
        /// into an <see cref="ObjectUniqueId"/> instance.
        /// </summary>
        /// <remarks>The method interprets the input string as follows:
        /// - If the string starts with 'A', the remainder of the string is parsed as a GUID.
        /// - If the string does not start with 'A', it is parsed as non-negative decimal digits.
        /// If the string is <see langword="null"/> or empty, or if the parsing fails,
        /// the method returns <see langword="null"/>.</remarks>
        /// <param name="s">The string to convert. The string can represent either a GUID prefixed
        /// with 'A' or a numeric value.</param>
        /// <returns>An <see cref="ObjectUniqueId"/> instance if the conversion is successful;
        /// otherwise, <see langword="null"/>.</returns>
        public static ObjectUniqueId? FromString(string? s)
        {
            if (s is null || s.Length == 0)
                return null;

            if (s[0] == 'A')
            {
                if (Guid.TryParse(s.AsSpan(1), out var g))
                {
                    return new ObjectUniqueId(g);
                }
            }

            else if (long.TryParse(
                s,
                NumberStyles.None,
                CultureInfo.InvariantCulture,
                out long l))
            {
                return new ObjectUniqueId(l);
            }

            return null;
        }

        /// <summary>
        /// Creates a new <see cref="ObjectUniqueId"/> instance using a newly generated GUID.
        /// </summary>
        /// <returns>A new <see cref="ObjectUniqueId"/> instance.</returns>
        public static ObjectUniqueId FromNewGuid()
        {
            return new ObjectUniqueId(Guid.NewGuid());
        }

        /// <summary>
        /// Creates a new <see cref="ObjectUniqueId"/> instance with an empty state.
        /// </summary>
        /// <returns>A new <see cref="ObjectUniqueId"/> instance with an empty state.</returns>
        public static ObjectUniqueId CreateEmpty()
        {
            return new ObjectUniqueId(StateKind.None, default, default, 0);
        }

        /// <summary>
        /// Indicates whether the current object is equal to another object.
        /// </summary>
        /// <param name="other">An object to compare with this object.</param>
        /// <returns><c>true</c> if the current object is equal to other; otherwise,
        /// <c>false</c>.</returns>
        public override readonly bool Equals([NotNullWhen(true)] object? other) =>
            other is ObjectUniqueId id && Equals(id);

        /// <summary>
        /// Indicates whether the current object is equal to another object of the same type.
        /// </summary>
        /// <param name="other">An object to compare with this object.</param>
        /// <returns><c>true</c> if the current object is equal to other; otherwise,
        /// <c>false</c>.</returns>
        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly bool Equals(ObjectUniqueId other) => this == other;

        /// <summary>
        /// Returns the hash code of this instance.
        /// </summary>
        /// <returns></returns>
        public override int GetHashCode()
        {
            return hashCode;
        }

        /// <summary>
        /// Returns a string that represents the current object.
        /// </summary>
        /// <returns>A string that represents the current object.</returns>
        public override string ToString()
        {
            if (state == StateKind.None)
                return string.Empty;

            // This format should not be changed as it is used in serialization.
            if (state == StateKind.Guid)
                return $"A{guid:N}";
            return id.ToString(CultureInfo.InvariantCulture);
        }

        [Conditional("DEBUG")]
        private static void TestOverflow()
        {
#pragma warning disable
            var id1 = new ObjectUniqueId();
            globalCounter = long.MaxValue - 1;
            var id2 = new ObjectUniqueId();

            var id3 = new ObjectUniqueId();

            globalCounter = -1;
            var id4 = new ObjectUniqueId();
#pragma warning restore
        }
    }
}
